CREATE TABLE chat_personas(id UUID PRIMARY KEY,room_id VARCHAR(40) NOT NULL REFERENCES chat_rooms(id),name VARCHAR(80) NOT NULL,instructions TEXT NOT NULL CHECK(octet_length(instructions)<=4096),memory TEXT NOT NULL DEFAULT '' CHECK(octet_length(memory)<=2048),cooldown_seconds INTEGER NOT NULL DEFAULT 2 CHECK(cooldown_seconds BETWEEN 1 AND 30),enabled BOOLEAN NOT NULL DEFAULT true,revision BIGINT NOT NULL DEFAULT 0,last_spoke_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX chat_personas_room ON chat_personas(room_id,created_at,id);
CREATE TABLE chat_persona_runs(id UUID PRIMARY KEY,room_id VARCHAR(40) NOT NULL REFERENCES chat_rooms(id),parameters JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN ('running','completed','failed','cancelled','budget_exhausted')),max_turns INTEGER NOT NULL CHECK(max_turns BETWEEN 1 AND 8),max_output_budget INTEGER NOT NULL CHECK(max_output_budget BETWEEN 512 AND 16384),reserved_tokens INTEGER NOT NULL DEFAULT 0,result JSONB NOT NULL DEFAULT '[]',updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chat_ai_room_locks(room_id VARCHAR(40) PRIMARY KEY REFERENCES chat_rooms(id),lease_token UUID NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
